/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import ast, copy, hashlib, json
root=Path('/workspace')
r=json.loads((root/'runtime.json').read_text())
p=json.loads((root/'proposal.json').read_text())

def validate(x,s,path='study'):
 typ=s.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool,'number':(int,float),'integer':int}
 if typ:
  assert isinstance(x,types[typ]),(path,'type',typ)
 if 'const' in s: assert x==s['const'],(path,'const')
 if 'enum' in s: assert x in s['enum'],(path,'enum')
 if isinstance(x,dict):
  assert all(k in x for k in s.get('required',[])),(path,'required')
  if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),(path,'minItems')
  if 'items' in s:
   for i,v in enumerate(x):validate(v,s['items'],path+'['+str(i)+']')
 if isinstance(x,str):assert len(x)>=s.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
vs=p['variants']; assert 1<=len(vs)<=4
assert len(set(v['name'] for v in vs))==len(vs)
assert len(set(v['file'] for v in vs))==len(vs)
assert any(v['role']=='candidate' for v in vs)
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
normalized=[]
for v in vs:
 assert v['role'] in ['candidate','control']
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 source=(root/v['file']).read_text()
 tree=ast.parse(source,filename=v['file'])
 compile(source,v['file'],'exec')
 config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 cfg=ast.literal_eval(config_node.value)
 assert cfg==v['config']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','compile','__import__','input'}
  if isinstance(n,ast.Attribute): assert n.attr not in {'load','save','from_pretrained','load_state_dict'}
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 assert set(cfg)<=set(a.arg for a in init.args.args)
 config_node.value=ast.Constant(None)
 normalized.append(ast.dump(tree,include_attributes=False))
 print(v['name'],v['file'],'sha256',hashlib.sha256(source.encode()).hexdigest())
assert len(set(normalized))==1,'Modules differ beyond CONFIG'
assert {(v['config']['raw_values'],v['config']['event_feedback']) for v in vs}=={(True,True),(False,True),(True,False),(False,False)}
for a in p['knowledge_assessments']:
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<=set(v['name'] for v in vs)
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
print('PASS: study schema, protocol/evidence/parent references, four-cell factorial, architecture-only configs, standalone source boundaries, syntax, and baseline preservation.')
print('All module ASTs match after removing CONFIG; forward operation structure is aligned. Backward cost remains unmeasured.')
print('No model execution or training was performed; host numerical integrity gates are recorded in cost_plan.')
PY"

